const trial_id = "multi_tenant_concurrency_control__iE4rvnd";

export const multiTenantQueue = queue({
  name: `multi-tenant-queue-${trial_id}`,
  concurrencyLimit: 10,
});

export const multiTenantTask = task({
  id: `multi-tenant-task-${trial_id}`,
  queue: multiTenantQueue,
  concurrencyKey: (payload: { userId: string; jobId: string }) => payload.userId,
  run: async (payload: { userId: string; jobId: string }, { ctx }) => {
    await new Promise((resolve) => setTimeout(resolve, 5000));

    return {
      userId: payload.userId,
      jobId: payload.jobId,
      startedAt: ctx.run.startedAt,
      finishedAt: new Date(), // Trigger.dev ctx doesn't easily expose finishedAt before it finishes, we'll just return a Date or use ctx or whatever. Actually, the requirements say "startedAt / finishedAt timestamps from the task context." Wait, context doesn't have finishedAt because it's still running. Let's return new Date().
      // Wait, let's check trigger.dev v3 docs for what's available.
    };
  },
});

